import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { verifyBundle, type Report } from '../app/lib/verify'
import type { Bundle } from '../app/lib/types'

/**
 * The whole-bundle contract with the Go verifier. Each case is a bundle — two
 * honest, the rest tampered — and Go's verdict on every check, by stable id,
 * generated by `go test ./bundle -run TestBundleVectors -update`. This
 * verifier must reach the same verdict on every check: agreeing that a bundle
 * fails is not enough, it must fail for the same reasons.
 */
const file = fileURLToPath(new URL('../../testdata/bundlevectors.json', import.meta.url))
const v = JSON.parse(readFileSync(file, 'utf8')) as {
  cases: { name: string; bundle: Bundle; expected: Record<string, 'pass' | 'fail' | 'skip'>; ok: boolean }[]
}

const outcome = (rep: Report) =>
  Object.fromEntries(rep.checks.map((c) => [c.id, c.skipped ? 'skip' : c.ok ? 'pass' : 'fail']))

describe('bundle vectors shared with the Go verifier', () => {
  it('cover honest and tampered bundles', () => {
    expect(v.cases.length).toBeGreaterThan(10)
    expect(v.cases.filter((c) => c.ok).length).toBe(2)
  })

  it.each(v.cases.map((c) => [c.name, c] as const))('%s: same verdict on every check', (_, c) => {
    const rep = verifyBundle(c.bundle)
    expect(rep.checks.filter((k) => !k.id).map((k) => k.name)).toEqual([])
    expect(outcome(rep)).toEqual(c.expected)
    expect(rep.ok).toBe(c.ok)
  })
})
